import { TextureProcedureRegister } from "../Procedures/TextureProcedureRegister";
export function GetTexture(builder, data, closestFace, primitive) {
    if (typeof data == "number") {
        builder.vars.textureIndex = data;
    }
    else {
        const procedure = TextureProcedureRegister.get(data.type);
        builder.vars.textureIndex = procedure.getTexture(builder, data, closestFace, primitive);
        procedure.transformUVs(builder, data, closestFace, primitive);
        procedure.getOverlayTexture(builder, data, closestFace, primitive, builder.vars.overlayTextures);
    }
}
